/**
 * @param {number} n
 * @return {number}
 */
var reinitializePermutation = function(n) {
    let pos = 1, steps = 0;
    while (true) {
        if (pos < Math.floor(n / 2)) {
            pos = 2 * pos;
        } else {
            pos = 2 * pos - (n - 1);
        }
        steps++;
        if (pos === 1) break;
    }
    return steps;
};
